#!/usr/bin/env bash
# Installs or upgrades the ZhuWei-RASP Java agent from an unpacked package (the dist/rasp directory).
#
#   tools/install.sh [--prefix /opt/rasp] [--properties rasp.properties] [--app-user USER]
#                    [--tomcat CATALINA_BASE] [--dry-run]
#
#   --prefix      install directory (default /opt/rasp)
#   --properties  rasp.properties generated by the console (contains app.secret and policy.public_key)
#   --app-user    OS user the Java application runs as; gets read access to conf/ and write access to
#                 logs/ and cache/ (requires root). Without it, files belong to the current user.
#   --tomcat      also enable the agent for this Tomcat (adds a marked block to bin/setenv.sh)
#
# Upgrades keep conf/ (new defaults are written next to it as *.new) and keep the previous jars under
# backup/<version>-<time>/ for rollback. Jars are replaced by rename, so running JVMs keep using the
# files they opened; restart the applications to pick up the new version.
set -euo pipefail

SRC="$(cd "$(dirname "$0")/.." && pwd)"
PREFIX=/opt/rasp PROPS="" APP_USER="" TOMCAT="" DRY=0
while [ $# -gt 0 ]; do
  case "$1" in
    --prefix) PREFIX="${2:?--prefix needs a directory}"; shift 2 ;;
    --properties) PROPS="${2:?--properties needs a file}"; shift 2 ;;
    --app-user) APP_USER="${2:?--app-user needs a user}"; shift 2 ;;
    --tomcat) TOMCAT="${2:?--tomcat needs CATALINA_BASE}"; shift 2 ;;
    --dry-run) DRY=1; shift ;;
    -h|--help) sed -n '2,18p' "$0"; exit 0 ;;
    *) echo "未知参数：$1（--help 查看用法）" >&2; exit 2 ;;
  esac
done

fail() { echo "安装失败：$*" >&2; exit 1; }
run() { if [ "$DRY" = 1 ]; then echo "+ $*"; else "$@"; fi; }

case "$PREFIX" in
  /*) ;;
  *) fail "--prefix 必须是绝对路径：$PREFIX" ;;
esac
GIVEN="$PREFIX"
while [ "${PREFIX%/}" != "$PREFIX" ]; do PREFIX="${PREFIX%/}"; done
case "$PREFIX" in
  ""|/bin|/boot|/dev|/etc|/home|/lib|/opt|/proc|/root|/sbin|/sys|/tmp|/usr|/var) fail "拒绝安装到系统目录 '$GIVEN'，请使用独立目录（如 /opt/rasp）" ;;
esac
for f in rasp-launcher.jar rasp-bootstrap.jar rasp-core.jar conf/rasp.properties conf/policy.json; do
  [ -f "$SRC/$f" ] || fail "安装包不完整，缺少 $f（请在解压后的 rasp 目录中运行 tools/install.sh）"
done
[ "$SRC" != "$PREFIX" ] || fail "安装包目录与安装目录相同：$PREFIX"
[ -z "$PROPS" ] || [ -f "$PROPS" ] || fail "找不到配置文件 $PROPS"
if [ -n "$APP_USER" ]; then
  [ "$(id -u)" = 0 ] || fail "--app-user 需要以 root 运行"
  id "$APP_USER" >/dev/null 2>&1 || fail "用户 $APP_USER 不存在"
  APP_GROUP="$(id -gn "$APP_USER")"
fi
if [ -n "$TOMCAT" ]; then
  [ -d "$TOMCAT/bin" ] || fail "$TOMCAT 不是 Tomcat 目录（缺少 bin/）"
fi

NEW_VERSION="$(sed -n 's/^version=//p' "$SRC/VERSION" 2>/dev/null || true)"
OLD_VERSION=""
[ -f "$PREFIX/VERSION" ] && OLD_VERSION="$(sed -n 's/^version=//p' "$PREFIX/VERSION" || true)"
if [ -n "$OLD_VERSION" ]; then echo "==> 升级 $PREFIX：${OLD_VERSION} -> ${NEW_VERSION:-unknown}"; else echo "==> 安装 ZhuWei-RASP ${NEW_VERSION:-unknown} 到 $PREFIX"; fi

run mkdir -p "$PREFIX/conf" "$PREFIX/logs" "$PREFIX/cache" "$PREFIX/tools"

# Keep the previous jars for rollback (tools/install.sh of the old package, or copy them back).
if [ -f "$PREFIX/rasp-core.jar" ]; then
  BK="$PREFIX/backup/${OLD_VERSION:-unknown}-$(date +%Y%m%d%H%M%S)"
  run mkdir -p "$BK"
  for f in rasp-launcher.jar rasp-bootstrap.jar rasp-core.jar VERSION; do
    [ -f "$PREFIX/$f" ] && run cp -p "$PREFIX/$f" "$BK/"
  done
  echo "    旧版本已备份到 $BK"
fi

# Jars: copy to a temp name, then rename over the old file (never overwrite a jar a JVM has open).
for f in rasp-launcher.jar rasp-bootstrap.jar rasp-core.jar; do
  run cp "$SRC/$f" "$PREFIX/.$f.tmp"
  run chmod 644 "$PREFIX/.$f.tmp"
  run mv -f "$PREFIX/.$f.tmp" "$PREFIX/$f"
done
for f in "$SRC"/tools/*.sh; do
  run cp "$f" "$PREFIX/tools/"
done
run chmod 755 "$PREFIX"/tools/*.sh
[ -f "$SRC/VERSION" ] && run cp "$SRC/VERSION" "$PREFIX/VERSION"

# Configuration: never overwrite what operators changed. rasp.properties is per-host (credentials),
# so only policy.json gets a .new copy of the new defaults for comparison.
[ -f "$PREFIX/conf/rasp.properties" ] || run cp "$SRC/conf/rasp.properties" "$PREFIX/conf/rasp.properties"
if [ ! -f "$PREFIX/conf/policy.json" ]; then
  run cp "$SRC/conf/policy.json" "$PREFIX/conf/policy.json"
elif ! cmp -s "$SRC/conf/policy.json" "$PREFIX/conf/policy.json"; then
  run cp "$SRC/conf/policy.json" "$PREFIX/conf/policy.json.new"
  echo "    保留现有 conf/policy.json，新版默认策略写入 conf/policy.json.new"
fi
if [ -n "$PROPS" ]; then
  run cp "$PROPS" "$PREFIX/conf/rasp.properties"
  echo "    已写入 conf/rasp.properties（来自 $PROPS）"
fi

# Permissions: conf holds app.secret; logs/cache must be writable by the application user.
run chmod 755 "$PREFIX" "$PREFIX/tools"
if [ -n "$APP_USER" ]; then
  run chown -R root:root "$PREFIX"
  run chown root:"$APP_GROUP" "$PREFIX/conf" "$PREFIX"/conf/*
  run chmod 750 "$PREFIX/conf"
  run chmod 640 "$PREFIX"/conf/*
  run chown -R "$APP_USER":"$APP_GROUP" "$PREFIX/logs" "$PREFIX/cache"
  run chmod 750 "$PREFIX/logs" "$PREFIX/cache"
else
  run chmod 700 "$PREFIX/conf" "$PREFIX/logs" "$PREFIX/cache"
  run chmod 600 "$PREFIX"/conf/*
  [ "$(id -u)" = 0 ] && echo "    提示：以 root 安装且未指定 --app-user，应用用户可能无法读取 conf/ 或写入 logs/" >&2
fi

if ! grep -q '^server.url=.\+' "$PREFIX/conf/rasp.properties" 2>/dev/null; then
  echo "    注意：conf/rasp.properties 未配置 server.url，Agent 将以独立模式运行（策略取自 conf/policy.json）"
elif ! grep -q '^policy.public_key=.\+' "$PREFIX/conf/rasp.properties" 2>/dev/null; then
  echo "    注意：未配置 policy.public_key，平台下发的策略不会被验签（请使用控制台生成的完整配置）" >&2
fi

MARK_BEGIN="# >>> zhuwei-rasp >>>"
if [ -n "$TOMCAT" ]; then
  SETENV="$TOMCAT/bin/setenv.sh"
  if [ -f "$SETENV" ] && grep -qF "$MARK_BEGIN" "$SETENV"; then
    echo "    $SETENV 已包含 RASP 配置，未重复添加"
  else
    if [ "$DRY" = 1 ]; then echo "+ append agent block to $SETENV"; else
      {
        echo ""
        echo "$MARK_BEGIN"
        echo "# added by $PREFIX/tools/install.sh; remove with $PREFIX/tools/uninstall.sh --tomcat $TOMCAT"
        echo "CATALINA_OPTS=\"\$CATALINA_OPTS -javaagent:$PREFIX/rasp-launcher.jar\""
        echo "# <<< zhuwei-rasp <<<"
      } >> "$SETENV"
      chmod +x "$SETENV"
    fi
    echo "    已在 $SETENV 中启用 Agent，重启 Tomcat 后生效"
  fi
fi

echo "==> 完成"
echo "    启动参数：-javaagent:$PREFIX/rasp-launcher.jar"
echo "    不重启接入：$PREFIX/tools/rasp-attach.sh attach <pid>"
echo "    紧急停用：touch $PREFIX/DISABLE"
